Here it is: dedup on original values (first of each run wins), then trim ASCII whitespace from the survivors.

```rust
pub fn squash(v: &mut Vec<String>) {
    // Pass 1: remove consecutive duplicate runs in place, comparing ORIGINAL
    // (untrimmed) values, keeping the first element of each run.
    let mut keep = 0usize;
    let len = v.len();
    for i in 0..len {
        if keep == 0 || v[i].as_str() != v[keep].as_str() {
            v[keep] = v[i].clone();
            keep += 1;
        }
    }
    v.truncate(keep);

    // Pass 2: trim ASCII whitespace from both ends of every surviving string.
    for s in v.iter_mut() {
        *s = s.trim_matches(|c: char| c.is_ascii_whitespace()).to_string();
    }
}
