use std::collections::{HashMap, VecDeque};
use std::hash::Hash;

/// A generic LRU (least-recently-used) cache.
///
/// `order` holds the keys with the least-recently-used entry at the front
/// and the most-recently-used entry at the back, mirroring `map`.
pub struct Lru<K, V> {
    cap: usize,
    map: HashMap<K, V>,
    order: VecDeque<K>,
}

impl<K: Eq + Hash + Clone, V> Lru<K, V> {
    /// Creates an empty cache with the given capacity (must be >= 1).
    pub fn new(cap: usize) -> Self {
        assert!(cap >= 1, "capacity must be at least 1");
        Lru {
            cap,
            map: HashMap::with_capacity(cap),
            order: VecDeque::new(),
        }
    }

    /// Returns the value stored for `k`, if present, and marks the entry
    /// as most-recently-used.
    pub fn get(&mut self, k: &K) -> Option<&V> {
        if self.map.contains_key(k) {
            if let Some(pos) = self.order.iter().position(|x| x == k) {
                self.order.remove(pos);
            }
            self.order.push_back(k.clone());
            self.map.get(k)
        } else {
            None
        }
    }

    /// Inserts `k` mapped to `v`, marking it as most-recently-used.
    /// If the key is new and the cache is full, the least-recently-used
    /// entry is evicted.
    pub fn put(&mut self, k: K, v: V) {
        if self.map.contains_key(&k) {
            if let Some(pos) = self.order.iter().position(|x| x == &k) {
                self.order.remove(pos);
            }
            self.order.push_back(k.clone());
            self.map.insert(k, v);
        } else if self.map.len() >= self.cap {
            if let Some(lru_key) = self.order.pop_front() {
                self.map.remove(&lru_key);
            }
            self.map.insert(k, v);
            self.order.push_back(k);
        } else {
            self.map.insert(k, v);
            self.order.push_back(k);
        }
    }
}
