pub fn parallel_map<T, R, F>(items: Vec<T>, f: F, workers: usize) -> Vec<R>
where
    T: Send + 'static,
    R: Send + 'static,
    F: Fn(T) -> R + Send + Sync + 'static,
{
    use std::sync::{mpsc, Arc};

    let len = items.len();
    let f = Arc::new(f);
    let (tx, rx) = mpsc::channel::<(usize, R)>();

    // Round-robin partition the (index, item) pairs across exactly `workers` chunks.
    let mut chunks: Vec<Vec<(usize, T)>> = vec![Vec::new(); workers];
    for (i, item) in items.into_iter().enumerate() {
        chunks[i % workers].push((i, item));
    }

    // Spawn exactly `workers` threads; each maps its own chunk.
    for chunk in chunks {
        let tx = tx.clone();
        let f = Arc::clone(&f);
        std::thread::spawn(move || {
            for (i, item) in chunk {
                tx.send((i, f(item))).unwrap();
            }
        });
    }
    drop(tx);

    // Collect results into slots keyed by original index, preserving input order.
    let mut results: Vec<Option<R>> = (0..len).map(|_| None).collect();
    for _ in 0..len {
        let (i, r) = rx.recv().expect("parallel_map: result channel closed unexpectedly");
        results[i] = Some(r);
    }

    results
        .into_iter()
        .map(|slot| slot.expect("parallel_map: missing result"))
        .collect()
}
