Waker design: `block_on` creates a waker backed by an `Arc<WakeState>` (`std::task::Wake` impl) that counts wake permits and unparks the `block_on` thread. After a `Pending` poll it parks, and only re-polls after consuming a wake permit — so wakes from another thread (or same-thread `wake_by_ref`) always drive the re-poll, with no lost-wakeup race between the check and `park()`.

```rust
use std::future::Future;
use std::pin::Pin;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::task::{Context, Poll, Wake, Waker};
use std::thread;

/// State shared between the `block_on` thread and the wakers it hands out.
struct WakeState {
    /// Thread running `block_on`; wakers unpark it so a pending `park()` returns.
    thread: thread::Thread,
    /// Wake notifications not yet consumed by the wait loop. Lets multiple
    /// wakes stack up and makes the wait loop race-free (no lost wakeups).
    permits: AtomicUsize,
}

/// Waker for `block_on`. Cheaply cloneable (via `Arc`), `Send + Sync`,
/// and safe to call from any thread.
#[derive(Clone)]
struct BlockOnWaker(Arc<WakeState>);

impl Wake for BlockOnWaker {
    fn wake(self: Arc<Self>) {
        self.wake_by_ref()
    }

    fn wake_by_ref(self: &Arc<Self>) {
        // Record the wake, then unpark the waiting thread. The Release
        // ordering pairs with the Acquire load in the wait loop, so any
        // state published by the waking thread is visible on re-poll.
        self.0.permits.fetch_add(1, Ordering::Release);
        self.0.thread.unpark();
    }
}

/// A future that yields (`Pending`) `remaining` times before completing.
pub struct YieldNow {
    pub remaining: u32,
}

impl Future for YieldNow {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        let this = self.get_mut();
        if this.remaining > 0 {
            this.remaining -= 1;
            cx.waker().wake_by_ref();
            Poll::Pending
        } else {
            Poll::Ready(())
        }
    }
}

/// Runs `fut` on the current thread until it completes.
///
/// The future is handed a waker that records a permit and unparks the current
/// thread. When the future reports `Pending`, this parks and only re-polls
/// after `wake()` has been called — which may be from another thread.
pub fn block_on<F: Future>(mut fut: F) -> F::Output {
    let state = Arc::new(WakeState {
        thread: thread::current(),
        permits: AtomicUsize::new(0),
    });
    let waker = Waker::from(Arc::new(BlockOnWaker(state.clone())));
    let mut cx = Context::from_waker(&waker);

    loop {
        if let Poll::Ready(out) = fut.as_mut().poll(&mut cx) {
            return out;
        }

        // The future is pending: wait until a wake() has been called before
        // polling again. The permit counter is the source of truth (a re-poll
        // only happens after consuming a permit), and the thread's sticky
        // unpark permit guarantees `park()` returns even if a wake lands
        // between the check and the park — so no wake is ever lost.
        loop {
            if state.permits.load(Ordering::Acquire) > 0 {
                state.permits.fetch_sub(1, Ordering::Acquire);
                break;
            }
            thread::park();
        }
    }
}
